local ECSComponent = import("Frame.ECS.ECSComponent")

---@class BackpackComponent
local BackpackComponent = Class("BackpackComponent", ECSComponent)

function BackpackComponent:__init()
    self.name = "BackpackComponent"
    ---@type table<string, number>
    self.backpack = {}
    ---背包类型与扩展次数
    ---@type table<string, number>
    self.backpackExtend = {}
    ---@type table<string, Constants.BackpackTypeId> @ 背包的道具类型map（key：道具类型，value：背包页签id）
    self.backpackGoodsTypeMap = {}
    ---@type table<Constants.BackpackTypeId, table<string, boolean>> @ 背包分类的红点map（key：背包页签id，value：道具id是否显示红点的map）
    self.backpackTypeRedPointMap = {}
end

function BackpackComponent:__delete()
    self.backpack = nil
    self.backpackExtend = nil
    self.backpackGoodsTypeMap = nil
    self.backpackTypeRedPointMap = nil
end

function BackpackComponent:Initial(jsonData, jsonDataExtend, jsonDataLocked)
    for _, backpackVo in ipairs(GoodsUtils.GetBasicPackets()) do
        for _, itemType in ipairs(backpackVo.itemType) do
            self.backpackGoodsTypeMap[tostring(itemType)] = backpackVo.id
        end
    end
    -- parse backpack data
    jsonData = checkTable(jsonData)
    for id, num in pairs(jsonData) do
        local type = GoodsUtils.GetIdType(id)
        if type ~= Constants.IDType.GoodsIgnoreType then
            self.backpack[tostring(id)] = checkNumber(num)
            self:UpdateGoodsBackpackRedPoint(id, true)
        end
    end
    -- parse backpackExtend data
    self.backpackExtend = checkTable(jsonDataExtend)
    self.backpackLocked = checkTable(jsonDataLocked)
end


---获取物品数量, 此处只用来内部获只给 GoodsUtils.GetThingNo 调用的
---@param goodsId integer
---@return integer
function BackpackComponent:GetGoodsNo(goodsId)
    local goodsId = checkInt(goodsId)
    local midFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local entryId = midFestivalComponent:GetActivityEnergyId()
    if checkInt(goodsId) == entryId then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
        return comp:GetActivityHp()
    end
    
    local dreamAdventuresMgr = import("Game.Activity.DreamAdventures.DreamAdventuresMgr"):GetInstance()
    if dreamAdventuresMgr:GetActivityHPId() and goodsId == checkInt(dreamAdventuresMgr:GetActivityHPId()) then
        return dreamAdventuresMgr:GetActivityHP()
    end
    
    ---@type ActivityCakeUtils
    local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')
    local entryId = ActivityCakeUtils.GetActivityHpId()
    if checkInt(goodsId) == entryId then
        return ActivityCakeUtils.GetActivityHpNum()
    end


    local ActivityCookingUtils = import("Game.UI.ActivityCooking.ActivityCookingUtils")
    local activityCookingConfigVo = ActivityCookingUtils.GetCookingConfigVo()
    if activityCookingConfigVo ~= nil and goodsId == activityCookingConfigVo.energyId then
        ---@type ActivityCookingComponent
        local ActivityCookingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityCookingComponent)
        if ActivityCookingComponent.dojo.hpData == nil then
            return 0
        end
        return ActivityCookingComponent.dojo.hpData.hp
    end

    ---@type MaidCoffeeManagerSettingVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 52)
    if not isNull(vo) and  checkNumber(vo.num) == goodsId then
        local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
        if isNull(maidCoffeeHomeDojo) then
            return 0
        else
            return checkNumber(maidCoffeeHomeDojo:GetSelfMerchantData().goodsNum)
        end
    end

    local BattleCardGameUtils = import('Game.UI.BattleCardGame.BattleCardGameUtils')
    local battleCardGameComp  = BattleCardGameUtils.GetComp()
    if goodsId == BattleCardGameUtils.GetHpGoodsId() then
        return battleCardGameComp:GetHpDojo().hpPoint
    end

    if isSet(self.backpack, checkString(goodsId)) then
        return self.backpack[checkString(goodsId)]
    end
    return 0
end


---更新背包数据量 此处只用来内部获只给 GoodsUtils.DrawRewards 调用的
---@param goodsId number
---@param num number
function BackpackComponent:UpdateGoodsNo(goodsId, num)
    local midFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local entryId = midFestivalComponent:GetActivityEnergyId()
    if checkInt(goodsId) == entryId then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
        comp:AddActivityHp(num)
        self:UpdateGoodsBackpackRedPoint(goodsId)
        return 
    end
    
    ---@type ActivityCakeUtils
    local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')
    local entryId = ActivityCakeUtils.GetActivityHpId()
    if checkInt(goodsId) == entryId then
        ActivityCakeUtils.UpdateActivityHpNum(num)
        return
    end
    
    local dreamAdventuresMgr = import("Game.Activity.DreamAdventures.DreamAdventuresMgr"):GetInstance()
    if dreamAdventuresMgr:GetActivityHPId() and goodsId == checkInt(dreamAdventuresMgr:GetActivityHPId()) then
        dreamAdventuresMgr:AddActivityHP(num)
        self:UpdateGoodsBackpackRedPoint(goodsId)
        return
    end

    local BattleCardGameUtils = import('Game.UI.BattleCardGame.BattleCardGameUtils')
    local battleCardGameComp  = BattleCardGameUtils.GetComp()
    if goodsId == BattleCardGameUtils.GetHpGoodsId() then
        battleCardGameComp:GetHpDojo():AppendHpPoint(num)
        return
    end
    
    local curNo = self:GetGoodsNo(goodsId)
    curNo = curNo + checkNumber(num)
    if curNo <= 0 then
        self.backpack[tostring(goodsId)] = nil
    else
        self.backpack[tostring(goodsId)] = curNo
    end
    self:UpdateGoodsBackpackRedPoint(goodsId)
end

---获得所有背包道具信息
---@return table<string, number>
function BackpackComponent:GetAllItems()
    return self.backpack
end

---@param goodsId integer
---@param isSkipCheckRedPoint boolean | nil
function BackpackComponent:UpdateGoodsBackpackRedPoint(goodsId, isSkipCheckRedPoint)
    local backpackGoodsId = checkInt(goodsId)
    ---@type GoodsVo
    local backpackGoodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(backpackGoodsId) or {}
    local backpackGoodsType = checkInt(backpackGoodsVo.type)
    local backpackGoodsNum = self:GetGoodsNo(backpackGoodsId)
    local backpackTypeId = checkInt(self.backpackGoodsTypeMap[tostring(backpackGoodsType)])
    if backpackTypeId > 0 and backpackGoodsVo.redPoint == 1 then
        if not self.backpackTypeRedPointMap[backpackTypeId] then
            self.backpackTypeRedPointMap[backpackTypeId] = {}
        end
        local redPointMap = self.backpackTypeRedPointMap[backpackTypeId]
        if backpackGoodsNum > 0 then
            redPointMap[tostring(backpackGoodsId)] = true
        else
            redPointMap[tostring(backpackGoodsId)] = false
        end
    end
    if isSkipCheckRedPoint then
    else
        self:CheckBackpackRedPoint()
    end
end

---@param backpackTypeId Constants.BackpackTypeId
---@return boolean
function BackpackComponent:IsBackpackTypeRedPoint(backpackTypeId)
    local hasRedPoint = false
    local redPointMap = checkTable(self.backpackTypeRedPointMap[checkInt(backpackTypeId)])
    for _, isRedPoint in pairs(redPointMap) do
        if isRedPoint then
            hasRedPoint = true
            break
        end
    end
    return hasRedPoint
end

---@param goodsType integer @ goodsConf.type, not Constants.IDType
---@return boolean
function BackpackComponent:IsBackpackGoodsTypeRedPoint(goodsType)
    local backpackTypeId = checkInt(self.backpackGoodsTypeMap[tostring(goodsType)])
    return self:IsBackpackTypeRedPoint(backpackTypeId)
end

---@param goodsId integer
---@return boolean
function BackpackComponent:IsBackpackGoodsIdRedPoint(goodsId)
    local backpackGoodsId = checkInt(goodsId)
    local backpackGoodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(backpackGoodsId) or {}
    local backpackGoodsType = checkInt(backpackGoodsVo.type)
    local backpackTypeId = checkInt(self.backpackGoodsTypeMap[tostring(backpackGoodsType)])
    local redPointMap = checkTable(self.backpackTypeRedPointMap[checkInt(backpackTypeId)])
    return (redPointMap[tostring(backpackGoodsId)] == true)
end

function BackpackComponent:CheckBackpackRedPoint()
    local hasRedPoint = false
    for backpackTypeId, _ in pairs(self.backpackTypeRedPointMap) do
        if self:IsBackpackTypeRedPoint(backpackTypeId) then
            hasRedPoint = true
            break
        end
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.Backpack, hasRedPoint and 1 or 0)
    return hasRedPoint
end

---GetCookieByIDType
---获取狗粮数据
--- cookieType = Constants.IDType.CharacterCardDogFood  --时得到的是卡牌狗粮卡
--- cookieType = Constants.IDType.TarotDogFood --时得到的是图型卡狗粮卡
---@param idType Constants.IDType @ id段类型
---@return table @ {id:string, goodsId:integer}
function BackpackComponent:GetCookieByIDType(idType)
    local t = {}
    idType = checkNumber(idType)
    for goodsId, num in pairs(self.backpack) do
        local goodType = GoodsUtils.GetIdType(goodsId)
        if goodType == idType then
            ---取出对应类型的狗粮卡,新版要打散数据
            if checkInt(num) > 0 then
                for i = 1, checkInt(num) do
                    table.insert(t, {
                        id = string.format('%s_%s_%s', tostring(goodsId), tostring(goodsId), tostring(i)),
                        goodsId = goodsId,
                    })
                end
            end
        end
    end
    return t
end

---GetGoodsByTypeId
---@param idType number 类型
function BackpackComponent:GetGoodsByTypeId(idType)
    local t = {}
    idType = checkNumber(idType)
    local configMgr = GoodsConfMgr:GetInstance()
    for goodsId, num in pairs(self.backpack) do
        if checkNumber(num) > 0 then
            local vo = configMgr:GetGoodsVoById(goodsId)
            if vo and checkNumber(vo.type) == idType then
                table.insert(t, {
                    goodsId = goodsId,
                    num = num,
                    vo = vo
                })
            end
        end
    end
    return t
end

---IsGoodsTypeFull
---背包格子上限
---@param idType number
---@param count number 指定类型的上限
function BackpackComponent:IsGoodsTypePacketFull(idType, count)
    local configMgr = GoodsConfMgr:GetInstance()
    idType = checkNumber(idType)
    local len = 0
    for goodsId, num in pairs(self.backpack) do
        local vo = configMgr:GetGoodsVoById(goodsId)
        if vo and checkNumber(vo.type) == idType then
            local stack = checkNumber(vo.stackMax)
            if stack > 0 then
                ---存在堆叠数量
                local cellNo, num2 = math.modf((checkNumber(num)) / stack)
                len = len + cellNo
                if num2 > 0 then
                    len = len + 1
                end
            else
                len = len + 1
            end
            if len >= count then
                break
            end
        end
    end
    return len >= count
end

---GetPacketLimitByType
---获取指定类型的背包上限
---@param packetId Constants.BackpackTypeId @ 背包基础表的id
function BackpackComponent:GetPacketLimitByPacketId(packetId)
    local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo
    local addNum = 0
    if playerDojo then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
        local isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))
        if isHavePrivilegeCard then
            addNum = GameUtils.GetPrivilegeCardAddNumByName(tonumber(vo.giftId), "boxNum") or 0
        end
    end
    ---@type BackpackVo
    local packet = GoodsUtils.GetBasicPacket(packetId)
    if self.backpackExtend[tostring(packetId)] then
        ---存在的情况下, 初始 + 次数* 每次数量
        return packet.initialNum + packet.cellNum * checkNumber(self.backpackExtend[tostring(packetId)]) + addNum
    else
        ---远程不存在的情况下，为配表的初始数量
        return packet.initialNum + addNum
    end
end

---GetPacketExtendNumber
---得到当前的扩展次数
---@param packetId number 包id
function BackpackComponent:GetPacketExtendNumber(packetId)
    if self.backpackExtend[tostring(packetId)] then
        return checkNumber(self.backpackExtend[tostring(packetId)])
    else
        return 0
    end
end

---UpdatePacketExtendNumber
---更新背包扩展次数
---@param packetId number 背包id
function BackpackComponent:UpdatePacketExtendNumber(packetId)
    if self.backpackExtend[tostring(packetId)] then
        self.backpackExtend[tostring(packetId)] = checkNumber(self.backpackExtend[tostring(packetId)]) + 1
    else
        self.backpackExtend[tostring(packetId)] = 1
    end
end

---GetGoodsByPacketId
---获到某一类型下的所有道具信息
---@param packetId Constants.BackpackTypeId
---@return table[]
function BackpackComponent:GetGoodsByPacketId(packetId)
    local t = {}
    ---@type BackpackVo
    local packet = GoodsUtils.GetBasicPacket(packetId)
    ---@type EquipmentComponent
    local equipmentComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    ---@type MaidCoffeePlayerComponent
    local coffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    for i, itemType in pairs(packet.itemType) do
        local goodsType = checkNumber(itemType)
        if goodsType == Constants.IDType.Equipment then
            ---如果是状态类型
            local equips = equipmentComponent:GetAllEquips()
            for _, v in pairs(equips) do
                table.insert(t, { goodsId = checkNumber(v.equipmentId), num = 1, vo = v })
            end
            ----经营相关道具
        elseif goodsType == Constants.IDType.RestaurantRecipeGoods or goodsType == Constants.IDType.RestaurantCookingGoods or goodsType == Constants.IDType.RestaurantMaterialGoods then
            local data = coffeePlayerComponent:GetPacketByType(goodsType)
            table.insertto(t, data)
        else
            local goods = self:GetGoodsByTypeId(itemType)
            table.insertto(t, goods)
        end
    end
    return t
end

--- 获到某一类型下的所有道具数量
---@param packetId Constants.BackpackTypeId
function BackpackComponent:GetGoodsNumByPacketId(packetId)
    local dataList = self:GetGoodsByPacketId(packetId)
    return #dataList
end

---GetBlindBoxData
---获得盲盒道具
function BackpackComponent:GetBlindBoxData()
    local _t = {}
    local t = checkTable(self:GetAllItems())
    for key, value in pairs(t) do
        local goodType = GoodsUtils.GetIdType(key)
        if goodType == Constants.IDType.GoodsCatBlindBox and checkNumber(value) > 0 then
            table.insert(_t, { goodsId = key, num = value })
        end
    end
    return _t
end

---获取背包锁定物品
function BackpackComponent:GetBackpackLocked()
    return self.backpackLocked
end

---判断物品是否被锁定
---@param goodsId integer
function BackpackComponent:IsGoodsLocked(goodsId)
    return checkInt(self.backpackLocked[tostring(goodsId)]) == 1
end

---设置道具锁定状态
---@param goodsId integer
---@param isLocked boolean
function BackpackComponent:SetGoodsLocked(goodsId, isLocked)
    if isLocked then
        self.backpackLocked[tostring(goodsId)] = 1
    else
        self.backpackLocked[tostring(goodsId)] = 0
    end
end

return BackpackComponent